ALTER TABLE "Vehicle" ALTER COLUMN "code" DROP NOT NULL, ALTER COLUMN "unit" DROP NOT NULL, ALTER COLUMN "mileage" DROP NOT NULL, ALTER COLUMN "mileage" DROP DEFAULT, ALTER COLUMN "status" SET DEFAULT 'UNKNOWN', ALTER COLUMN "availability" SET DEFAULT 'UNKNOWN', ADD COLUMN "profile" TEXT, ADD COLUMN "cargoVolumeM3" DECIMAL(7,2);
ALTER TABLE "Vehicle" ADD CONSTRAINT "Vehicle_positive_volume" CHECK ("cargoVolumeM3" IS NULL OR "cargoVolumeM3" > 0);
